//! 🧪️ Original9-byte argument groups enter final native storage with conserved birth and every interruption.
use super::*;
use pack::record::RetainedRecordBodySourceDecode;
use pack::record::RetainedRecordBodyToken;
use pack::record::RetainedValueContainer;
use pack::record::RetainedValueToken;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::RetainedCloneProgress;
use semio_framework_value::RetirementDemand;
use crate::ToolRunReceivingLimits;
use protocol::codec::{RetainedWireByteSource,OriginalWireSourceIdentity};
fn funds(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_depth>=d.depth&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes}
struct Pages<'a>{bytes:&'a[u8],identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for Pages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{self.bytes.chunks(7).nth(index/7)?.get(index%7).copied()}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
#[test]
fn original_typed_step_receiving_preserves_final_native_arguments_and_every_interruption(){
 let law:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/📝️step/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes=hex(law["bodyHex"].as_str().unwrap());let source=Pages{identity:OriginalWireSourceIdentity{address:bytes.as_ptr()as usize,extent:bytes.len(),authority:Some((42,7))},bytes:&bytes};
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let metadata=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 let corpus:serde_json::Value=serde_json::from_str(crate::fixture_text("🧪️tests/🧫️fixtures/🎞️ticks.json")).unwrap();let reference=crate::ToolRunTick::decode(&hex(corpus["ticks"][0]["hex"].as_str().unwrap())).unwrap();
 for stop in law["interruptAfter"].as_array().unwrap(){let stop=stop.as_u64().unwrap()as usize;let(mut lower,mut physical)=observe(||RetainedRecordBodySourceDecode::admit(&source,(0,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());lower.take_receipt().unwrap();
  let((mut typed,progress),heap)=observe(||ToolRunStepReceiving::admit(&lower,g).unwrap());assert_eq!(heap,(0,0));assert_eq!(typed.take_receipt().unwrap(),(g,progress));
  let(mut other,heap)=observe(||RetainedRecordBodySourceDecode::admit(&source,(1,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());assert_eq!(heap,(0,0));other.take_receipt().unwrap();assert_eq!(other.source_identity(),lower.source_identity());assert_ne!(other.original_range(),lower.original_range());let mut offered=Some(RetainedRecordBodyToken::Value(RetainedValueToken::Begin{kind:RetainedValueContainer::Record,count:4}));let before=offered;let(denied,heap)=observe(||typed.receive(&other,&mut offered,g));assert!(denied.is_err());assert_eq!(heap,(0,0));assert_eq!(offered,before);assert!(typed.receipt().is_none());drop(denied);other.cancel();while !other.terminal_is_empty(){let(_,heap)=observe(||other.close_step(g).unwrap());let(issued,p)=other.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;}let(_,heap)=observe(||drop(other));assert_eq!(heap,(0,0));
  let(mut pending,mut accepted,mut copied)=(None,0,0);
  for _ in 0..10000{if accepted>=stop||typed.step().is_some(){break}if lower.token().is_some(){let(result,heap)=observe(||lower.take_token_into(&mut pending,g).unwrap());assert!(result);assert_eq!(heap,(0,0));lower.take_receipt().unwrap();}
   if pending.is_some(){if !matches!(pending,Some(RetainedRecordBodyToken::Value(_))){assert!(matches!(pending,Some(RetainedRecordBodyToken::Catalog{symbols:0}|RetainedRecordBodyToken::CatalogComplete)));pending=None;continue}
    if matches!(pending,Some(RetainedRecordBodyToken::Value(RetainedValueToken::Byte(_))))&&typed.argument_at==0{let mut malformed=Some(RetainedRecordBodyToken::Value(RetainedValueToken::Byte(9)));let before=malformed;let scratch=typed.argument;let(result,heap)=observe(||typed.receive(&lower,&mut malformed,g));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(malformed,before);assert_eq!(typed.argument,scratch);assert!(typed.receipt().is_none());drop(result)}
    let before=pending;let d=typed.demands(&pending).unwrap();for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:1,..g}),if d.copy_bytes>0{Some(RetainedCloneGrant{maximum_copy_bytes:0,..g})}else{None},if d.capacity_bytes>0{Some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}else{None}].into_iter().flatten(){let(result,heap)=observe(||typed.receive(&lower,&mut pending,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(pending,before);assert!(typed.receipt().is_none())}
    let(result,heap)=observe(||typed.receive(&lower,&mut pending,g).unwrap());let p=result.unwrap();assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);assert!(pending.is_none());let mut blocked=before;assert!(typed.receive(&lower,&mut blocked,g).unwrap().is_none());assert_eq!(blocked,before);assert_eq!(typed.take_receipt().unwrap(),(g,p));copied+=p.copied_bytes;physical.0+=heap.0;physical.1+=heap.1;accepted+=1;continue
   }
   let(status,heap)=observe(||lower.step(&source,g).unwrap());assert_ne!(status,pack::record::RetainedRecordBodySourceStep::Fault);let(issued,p)=lower.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;
  }
  if stop==1000{assert_eq!(copied,18);assert_eq!(typed.step(),Some(&reference.steps[0]));let pointer=typed.step().unwrap().args.as_ptr();let mut recipient=None;assert!(typed.take_step_into(&mut recipient,RetainedCloneGrant{maximum_items:0,..metadata}).is_none());let(p,heap)=observe(||typed.take_step_into(&mut recipient,metadata).unwrap());assert_eq!(heap,(0,0));assert_eq!(recipient.as_ref(),Some(&reference.steps[0]));assert_eq!(recipient.as_ref().unwrap().args.as_ptr(),pointer);assert_eq!(typed.take_receipt().unwrap(),(metadata,p));assert_eq!(p.copied_bytes,0);let mut repeated=Some(RetainedRecordBodyToken::Value(RetainedValueToken::End(RetainedValueContainer::Record)));let before=repeated;let(blocked,heap)=observe(||typed.receive(&lower,&mut repeated,g).unwrap());assert!(blocked.is_none());assert_eq!(repeated,before);assert_eq!(heap,(0,0));
   while !recipient.as_ref().unwrap().args.is_empty(){let(_,heap)=observe(||recipient.as_mut().unwrap().args.pop());assert_eq!(heap,(0,0));assert!(RetainedCloneProgress{copied_items:1,..Default::default()}.fits(g));}
   let release=recipient.as_ref().unwrap().args.capacity()*std::mem::size_of::<ToolRunStepArg>();assert!(funds(g,RetirementDemand{release_bytes:release,depth:2,..Default::default()}));let((),heap)=observe(||drop(std::mem::take(&mut recipient.as_mut().unwrap().args)));assert_eq!(heap,(0,release));physical.1+=heap.1;let(_,heap)=observe(||recipient.take());assert_eq!(heap,(0,0));
  }
  typed.cancel();while !typed.terminal_is_empty(){let d=typed.close_demands().unwrap();if d.release_bytes>0{let(result,heap)=observe(||typed.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));}let(p,heap)=observe(||typed.close_step(g).unwrap().unwrap());assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);assert_eq!(p.copied_bytes,0);assert!(p.fits(g));assert_eq!(typed.take_receipt().unwrap(),(g,p));physical.0+=heap.0;physical.1+=heap.1;}
  lower.cancel();while !lower.terminal_is_empty(){if lower.token().is_some(){lower.take_token_into(&mut pending,g).unwrap();lower.take_receipt().unwrap();pending=None;}let(_,heap)=observe(||lower.close_step(g).unwrap());let(issued,p)=lower.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;}
  assert_eq!(physical.0,physical.1);let((),heap)=observe(||{drop(typed);drop(lower)});assert_eq!(heap,(0,0));
 }
}
